body.script:
(function () {
  const status = document.getElementById('godly-status');
  const splash = document.getElementById('godly-splash');
  const frame = document.getElementById('godly-viewport');
  const fallbackBtn = document.getElementById('godly-fallback-btn');

  let dismissed = false;
  function dismiss() {
    if (dismissed) return;
    dismissed = true;
    if (splash) {
      splash.style.opacity = '0';
      setTimeout(() => { splash.style.display = 'none'; }, 450);
    }
  }

  status.textContent = 'Launching celestial operating system...';

  frame.onload = () => {
    setTimeout(dismiss, 350);
  };

  const loc = window.location.href;
  const origin = window.location.origin || '';
  const isJsDelivr = loc.includes('cdn.jsdelivr.net');
  const isWasmer = loc.includes('wasmer.app') || loc.includes('wasmer.io');

  // Robust target resolution:
  // 1. If running on Wasmer, load /dist/ from the same Wasmer origin.
  // 2. If running on same domain over HTTP(S) and not jsDelivr, load ./dist/ relative.
  // 3. If running on jsDelivr or external host, load production bundle at donoela.github.io/Godly-OS-Workspac---Github/dist/
  let targetUrl = 'https://donoela.github.io/Godly-OS-Workspac---Github/dist/';
  if (isWasmer && origin && origin !== 'null') {
    targetUrl = origin + '/dist/';
  } else if (!isJsDelivr && origin && origin !== 'null' && window.location.protocol.startsWith('http')) {
    targetUrl = './dist/';
  }

  if (fallbackBtn) {
    fallbackBtn.href = targetUrl;
  }

  status.textContent = 'Connecting to production runtime (' + (isJsDelivr ? 'jsDelivr bridge' : 'direct mirror') + ')...';
  frame.src = targetUrl;

  // Failsafe: if frame takes longer than 4.5s (e.g. cross-origin framing restriction), reveal one-click launcher
  setTimeout(() => {
    if (!dismissed && fallbackBtn) {
      status.textContent = 'If environment blocks framing, launch directly:';
      fallbackBtn.style.display = 'inline-block';
    }
  }, 4500);
})();
